#!/bin/bash
# Idempotent HMS database access roles on the OFBiz database (public schema).
# Requires superuser connection (POSTGRES_USER). Passwords from environment only — never log them.
set -euo pipefail

: "${POSTGRES_USER:?POSTGRES_USER is required}"
: "${OFBIZ_POSTGRES_OFBIZ_DB:?OFBIZ_POSTGRES_OFBIZ_DB is required}"
: "${OFBIZ_POSTGRES_OFBIZ_USER:?OFBIZ_POSTGRES_OFBIZ_USER is required}"

POSTGRES_HMS_FULL_ACCESS_USER="${POSTGRES_HMS_FULL_ACCESS_USER:-hms_db_full}"
POSTGRES_HMS_WRITE_ACCESS_USER="${POSTGRES_HMS_WRITE_ACCESS_USER:-hms_db_write}"
POSTGRES_HMS_READ_ONLY_USER="${POSTGRES_HMS_READ_ONLY_USER:-hms_db_read}"

if [[ -z "${POSTGRES_HMS_FULL_ACCESS_PASSWORD:-}" || -z "${POSTGRES_HMS_WRITE_ACCESS_PASSWORD:-}" || -z "${POSTGRES_HMS_READ_ONLY_PASSWORD:-}" ]]; then
  echo "hms-access-roles: set POSTGRES_HMS_FULL_ACCESS_PASSWORD, POSTGRES_HMS_WRITE_ACCESS_PASSWORD, and POSTGRES_HMS_READ_ONLY_PASSWORD in docker/.env" >&2
  exit 1
fi

psql_super() {
  psql -v ON_ERROR_STOP=1 --username "${POSTGRES_USER}" "$@"
}

role_exists() {
  local role="$1"
  psql_super --dbname postgres -tAc "SELECT 1 FROM pg_roles WHERE rolname = '${role}'" | grep -q 1
}

ensure_login_role() {
  local role="$1"
  local pass="$2"
  if role_exists "${role}"; then
    return 0
  fi
  psql_super --dbname postgres -c "CREATE ROLE \"${role}\" LOGIN PASSWORD '${pass}'"
}

echo "hms-access-roles: ensuring login roles on database ${OFBIZ_POSTGRES_OFBIZ_DB} (app user ${OFBIZ_POSTGRES_OFBIZ_USER} unchanged)"

ensure_login_role "${POSTGRES_HMS_FULL_ACCESS_USER}" "${POSTGRES_HMS_FULL_ACCESS_PASSWORD}"
ensure_login_role "${POSTGRES_HMS_WRITE_ACCESS_USER}" "${POSTGRES_HMS_WRITE_ACCESS_PASSWORD}"
ensure_login_role "${POSTGRES_HMS_READ_ONLY_USER}" "${POSTGRES_HMS_READ_ONLY_PASSWORD}"

psql_super --dbname postgres <<-EOSQL
    REVOKE ALL ON DATABASE "${OFBIZ_POSTGRES_OFBIZ_DB}" FROM PUBLIC;
    GRANT CONNECT ON DATABASE "${OFBIZ_POSTGRES_OFBIZ_DB}" TO "${POSTGRES_HMS_FULL_ACCESS_USER}";
    GRANT CONNECT ON DATABASE "${OFBIZ_POSTGRES_OFBIZ_DB}" TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    GRANT CONNECT ON DATABASE "${OFBIZ_POSTGRES_OFBIZ_DB}" TO "${POSTGRES_HMS_READ_ONLY_USER}";
EOSQL

psql_super --dbname "${OFBIZ_POSTGRES_OFBIZ_DB}" <<-EOSQL
    REVOKE ALL ON SCHEMA public FROM "${POSTGRES_HMS_FULL_ACCESS_USER}";
    REVOKE ALL ON SCHEMA public FROM "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    REVOKE ALL ON SCHEMA public FROM "${POSTGRES_HMS_READ_ONLY_USER}";

    GRANT USAGE ON SCHEMA public TO "${POSTGRES_HMS_FULL_ACCESS_USER}";
    GRANT USAGE ON SCHEMA public TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    GRANT USAGE ON SCHEMA public TO "${POSTGRES_HMS_READ_ONLY_USER}";

    -- OFBiz entity engine (add-missing-on-start) needs DDL in public for new HMS entities.
    GRANT CREATE ON SCHEMA public TO "${OFBIZ_POSTGRES_OFBIZ_USER}";

    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO "${POSTGRES_HMS_FULL_ACCESS_USER}";
    GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO "${POSTGRES_HMS_FULL_ACCESS_USER}";

    REVOKE INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public FROM "${POSTGRES_HMS_READ_ONLY_USER}";
    GRANT SELECT ON ALL TABLES IN SCHEMA public TO "${POSTGRES_HMS_READ_ONLY_USER}";
    GRANT SELECT ON ALL SEQUENCES IN SCHEMA public TO "${POSTGRES_HMS_READ_ONLY_USER}";

    REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA public FROM "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public FROM "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    GRANT INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";

    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "${POSTGRES_HMS_FULL_ACCESS_USER}";
    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT USAGE, SELECT ON SEQUENCES TO "${POSTGRES_HMS_FULL_ACCESS_USER}";

    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT SELECT ON TABLES TO "${POSTGRES_HMS_READ_ONLY_USER}";
    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT SELECT ON SEQUENCES TO "${POSTGRES_HMS_READ_ONLY_USER}";

    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT INSERT, UPDATE, DELETE ON TABLES TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";
    ALTER DEFAULT PRIVILEGES FOR ROLE "${OFBIZ_POSTGRES_OFBIZ_USER}" IN SCHEMA public
        GRANT USAGE ON SEQUENCES TO "${POSTGRES_HMS_WRITE_ACCESS_USER}";
EOSQL

echo "hms-access-roles: done"
